package com.vandorlabs.physics;

import com.vandorlabs.gear.core.GearMotion;

/** Constraint equations checked independently from the fitter, including actual shared eased arm poses. */
public final class CouplerArmConstraintTest {
    private static int checks,profiles;
    private static void need(boolean v,String why){checks++;if(!v)throw new AssertionError("Coupler stroke fit: "+why);}
    private static CouplerArmConstraint.Stroke free(double requested){return new CouplerArmConstraint.Stroke(0,1,requested);}
    private static void exact(CouplerArmConstraint.Model model,CouplerArmConstraint.Result fit,RigidTransform desired,CouplerArmConstraint.Workspace scratch){
        need(fit.accepted(),"expected legal fit "+fit.failure+" error="+fit.error);double[] parameters=new double[fit.arms()],points=new double[12];for(int i=0;i<parameters.length;i++){parameters[i]=fit.progress(i);need(parameters[i]>=0&&parameters[i]<=1,"legal stroke");}need(model.evaluate(parameters,points),"source model");for(int pair=0;pair<2;pair++){int at=pair*6;double[] p=fit.transform.point(points[at+3],points[at+4],points[at+5]);need(Math.abs(p[0]-points[at])<1e-7&&Math.abs(p[1]-points[at+1])<1e-7&&Math.abs(p[2]-points[at+2])<1e-7,"both actual point equations");}for(int i=0;i<9;i++)need(fit.transform.r[i]==desired.r[i],"requested orientation remains exact");need(scratch.evaluations()<=CouplerArmConstraint.MAX_EVALUATIONS,"bounded evaluation count");profiles++;
    }
    public static void main(String[] args){
        CouplerArmConstraint.Model extenders=(progress,points)->{for(int i=0;i<2;i++){GearMotion.Vec p=GearMotion.pose(GearMotion.Mode.EXTEND,GearMotion.Direction.NORTH,4,progress[i]).transformFootVertex(0,0,i*4);int at=i*6;points[at]=p.x;points[at+1]=p.y;points[at+2]=p.z;points[at+3]=0;points[at+4]=0;points[at+5]=i*4;}return true;};
        CouplerArmConstraint.Workspace scratch=new CouplerArmConstraint.Workspace(2,2);
        for(int angle=-75;angle<=75;angle+=3)for(double a:new double[]{.1,.25,.45,.65,.9})for(double b:new double[]{.15,.35,.55,.75,.85}){RigidTransform desired=RigidTransform.rotation(0,0,1,angle);CouplerArmConstraint.Stroke[] strokes={free(a),free(b)};CouplerArmConstraint.Result fit=CouplerArmConstraint.solve(extenders,strokes,desired,scratch);exact(extenders,fit,desired,scratch);need(Math.abs(fit.progress(0)-fit.progress(1))<1e-6,"both strokes accommodate matching paired anchors");need(strokes[0].requested==a&&strokes[1].requested==b,"input controls immutable");}
        for(GearMotion.Mode mode:new GearMotion.Mode[]{GearMotion.Mode.EXTEND,GearMotion.Mode.ROTATE,GearMotion.Mode.ROTATE_LEVEL})for(GearMotion.Direction direction:GearMotion.Direction.values()){
            CouplerArmConstraint.Model curved=(progress,points)->{for(int i=0;i<2;i++){GearMotion.Vec p=GearMotion.pose(mode,direction,4,progress[i]).transformFootVertex(.5,-4,.5);int at=i*6;points[at]=p.x;points[at+1]=p.y;points[at+2]=p.z+i*4;points[at+3]=0;points[at+4]=0;points[at+5]=i*4;}return true;};
            for(int angle:new int[]{-60,-25,0,25,60})for(double a:new double[]{.2,.4,.6}){RigidTransform desired=RigidTransform.rotation(0,0,1,angle);CouplerArmConstraint.Result fit=CouplerArmConstraint.solve(curved,new CouplerArmConstraint.Stroke[]{free(a),free(.8)},desired,scratch);exact(curved,fit,desired,scratch);need(Math.abs(fit.progress(0)-fit.progress(1))<1e-5,"actual rotating/level curves fit shared stroke");}
        }
        CouplerArmConstraint.Result first=CouplerArmConstraint.solve(extenders,new CouplerArmConstraint.Stroke[]{free(.2),free(.4)},RigidTransform.rotation(0,0,1,-40),scratch),second=CouplerArmConstraint.solve(extenders,new CouplerArmConstraint.Stroke[]{free(.6),free(.8)},RigidTransform.rotation(0,0,1,40),scratch);need(first.accepted()&&second.accepted()&&Math.abs(first.transform.y-second.transform.y)>.5,"changed commands while twisting move current arm anchors and body translation");
        CouplerArmConstraint.Stroke[] exhausted={new CouplerArmConstraint.Stroke(0,.2,.1),new CouplerArmConstraint.Stroke(.8,1,.9)};need(CouplerArmConstraint.solve(extenders,exhausted,RigidTransform.IDENTITY,scratch).failure==CouplerArmConstraint.Failure.UNSATISFIED,"exhausted strokes refuse instead of rigid fallback");
        need(CouplerArmConstraint.solve(extenders,new CouplerArmConstraint.Stroke[]{free(.2),free(.8)},RigidTransform.rotation(1,0,0,20),scratch).failure==CouplerArmConstraint.Failure.UNSATISFIED,"unsupported lateral geometry refuses requested frame");
        need(CouplerArmConstraint.solve(extenders,new CouplerArmConstraint.Stroke[]{free(Double.NaN),free(.8)},RigidTransform.IDENTITY,scratch).failure==CouplerArmConstraint.Failure.STROKE,"nonfinite control refuses");need(CouplerArmConstraint.solve((p,out)->true,new CouplerArmConstraint.Stroke[]{free(.2),free(.8)},RigidTransform.IDENTITY,scratch).failure==CouplerArmConstraint.Failure.MODEL,"incomplete model cannot reuse stale scratch");
        CouplerArmConstraint.Model single=(p,out)->{out[0]=p[0]*3;out[1]=2;out[2]=-1;out[3]=4;out[4]=1;out[5]=2;return true;};CouplerArmConstraint.Workspace one=new CouplerArmConstraint.Workspace(1,1);for(int axis=0;axis<3;axis++)for(int angle=-75;angle<=75;angle+=5){RigidTransform r=RigidTransform.rotation(axis==0?1:0,axis==1?1:0,axis==2?1:0,angle);CouplerArmConstraint.Result fit=CouplerArmConstraint.solve(single,new CouplerArmConstraint.Stroke[]{free(.37)},r,one);need(fit.accepted()&&fit.progress(0)==.37,"single pair retains ordinary requested orientation and unchanged legal stroke");double[] point=fit.transform.point(4,1,2);need(Math.abs(point[0]-1.11)<1e-10&&Math.abs(point[1]-2)<1e-10&&Math.abs(point[2]+1)<1e-10,"single pair head coincidence");}
        need(scratch.retainedBytes()<4096&&new CouplerArmConstraint.Workspace(64,64).retainedBytes()<160000,"scratch retained byte bound");System.out.println("Coupler bounded stroke fitting PASS profiles="+profiles+" checks="+checks+" Source eased Extender points/Z twist/changing controls/single pair freedoms/stroke exhaustion/refusal; world solve unbound");
    }
}
